const items = $input.all();
const body = items[0].json.body || items[0].json;

// Solo procesar messages.upsert
const event = body.event || '';
if (event !== 'messages.upsert') {
  return [{ json: { phone: '', respuesta: '', needsAPI: false, intent: '', apiMethod: 'GET' } }];
}

const data = body.data || {};
const key = data.key || {};

// Ignorar mensajes propios y de grupos
if (key.fromMe || (key.remoteJid || '').includes('@g.us')) {
  return [{ json: { phone: '', respuesta: '', needsAPI: false, intent: '', apiMethod: 'GET' } }];
}

// Extraer texto
const msg = data.message || {};
const text = (msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '').trim();
if (!text) {
  return [{ json: { phone: '', respuesta: '', needsAPI: false, intent: '', apiMethod: 'GET' } }];
}

const phone = (key.remoteJid || '').replace('@s.whatsapp.net', '');
let comando = text.toLowerCase().trim();
const API = 'https://api-sg.hato-pascher.com';

// Atajos numéricos: expandir número a comando
const atajos = { '1': 'catalogo', '2': 'buscar', '3': 'precio', '4': 'estado', '5': 'pedido' };
const partes = comando.split(/\s+/);
if (atajos[partes[0]]) {
  partes[0] = atajos[partes[0]];
  comando = partes.join(' ');
}

let respuesta = '';
let needsAPI = false;
let apiUrl = '';
let intent = '';
let args = '';
let apiMethod = 'GET';
let apiBody = '';

if (['menu', 'hola', 'ayuda', 'hi', 'hello', 'inicio', '0'].includes(comando)) {
  intent = 'menu';
  respuesta = '*🏭 El Hato Pascher C.A.*\n\n' +
    'Escribe el número o el comando:\n\n' +
    '*1.* 📦 *catalogo* — lista de productos\n' +
    '*2.* 🔍 *buscar [texto]* — buscar producto\n' +
    '*3.* 💲 *precio [código]* — precio de un producto\n' +
    '*4.* 📝 *estado [PIN] [CLIENTE]* — consulta de cuenta (operador)\n' +
    '*5.* 🛒 *pedido* — hacer un pedido\n\n' +
    '_Ejemplo: 2 slalon  ó  buscar slalon_';

} else if (comando === 'catalogo' || comando === 'productos') {
  intent = 'catalogo';
  needsAPI = true;
  apiUrl = API + '/api/wa/catalogo';

} else if (comando.startsWith('buscar ')) {
  intent = 'buscar';
  args = comando.slice(7).trim();
  if (!args) {
    respuesta = 'Escribe qué producto buscas.\n_Ejemplo: 2 slalon_';
  } else {
    needsAPI = true;
    apiUrl = API + '/api/wa/catalogo?q=' + encodeURIComponent(args);
  }

} else if (comando === 'buscar') {
  intent = 'buscar';
  respuesta = 'Escribe qué producto buscas.\n_Ejemplo: 2 slalon_';

} else if (comando.startsWith('precio ')) {
  intent = 'precio';
  args = comando.slice(7).trim();
  if (!args) {
    respuesta = 'Escribe el código del producto.\n_Ejemplo: 3 771000_';
  } else {
    needsAPI = true;
    apiUrl = API + '/api/wa/producto/' + encodeURIComponent(args);
  }

} else if (comando === 'precio') {
  intent = 'precio';
  respuesta = 'Escribe el código del producto.\n_Ejemplo: 3 771000_';

} else if (comando.startsWith('estado ') || comando.startsWith('abono ') || comando.startsWith('pagos ') || comando.startsWith('abonos ')) {
  intent = 'estado';
  const prefijos = ['estado ', 'abono ', 'pagos ', 'abonos '];
  const prefijo = prefijos.find(p => comando.startsWith(p));
  const resto = comando.slice(prefijo.length).trim();
  const tokens = resto.split(/\s+/);

  if (tokens.length < 2 || !tokens[0]) {
    respuesta = 'Formato: *estado [PIN] [CODIGO_CLIENTE]*\n_Ejemplo: 4 123456 CLI001_';
  } else {
    const pin = tokens[0];
    const codCliente = tokens.slice(1).join(' ').toUpperCase();

    if (pin.length !== 6 || !/^\d{6}$/.test(pin)) {
      respuesta = 'El PIN debe ser de 6 dígitos numéricos.\n_Ejemplo: 4 123456 CLI001_';
    } else {
      needsAPI = true;
      apiUrl = API + '/api/wa/estado-cuenta';
      apiMethod = 'POST';
      apiBody = JSON.stringify({ pin, codigoCliente: codCliente });
    }
  }

} else if (['estado', 'abono', 'pagos', 'abonos'].includes(comando)) {
  intent = 'estado';
  respuesta = 'Formato: *estado [PIN] [CODIGO_CLIENTE]*\n_Ejemplo: 4 123456 CLI001_';

} else if (comando === 'pedido') {
  intent = 'pedido_ayuda';
  respuesta = '*🛒 Realizar Pedido*\n\n' +
    'Envía tu pedido en un solo mensaje con este formato:\n\n' +
    '*pedido Nombre, Teléfono, productos*\n\n' +
    '_Ejemplo:_\n' +
    '_pedido Juan Pérez, 0414-1234567, 2 TUB001, 5 SLA002, 1 CEM003_\n\n' +
    'Puedes usar los códigos del *catálogo* (escribe 1).';

} else if (comando.startsWith('pedido ')) {
  intent = 'pedido';
  const contenido = text.slice(7).trim();
  const segmentos = contenido.split(',').map(s => s.trim());
  if (segmentos.length < 3) {
    respuesta = 'Formato incorrecto.\n\nUsa: *pedido Nombre, Teléfono, productos*\n_Ejemplo: pedido Juan, 0414-123, 2 TUB001, 5 SLA002_';
  } else {
    const nombre = segmentos[0];
    const tel = segmentos[1];
    const prods = segmentos.slice(2).join(', ');
    needsAPI = true;
    apiUrl = API + '/api/wa/pedido?nombre=' + encodeURIComponent(nombre) +
      '&tel=' + encodeURIComponent(tel) +
      '&items=' + encodeURIComponent(prods) +
      '&wa=' + phone;
    args = JSON.stringify({ nombre, tel, items: prods });
  }

} else {
  intent = 'default';
  respuesta = 'No entendí "' + text + '".\n\nEscribe *menu* para ver las opciones.';
}

return [{ json: { phone, respuesta, needsAPI, apiUrl, intent, args, apiMethod, apiBody } }];

const items = $input.all();
const apiResp = items[0].json;
const prep = $('Preparar').first().json;
const intent = prep.intent;

let respuesta = '';

try {
  if (intent === 'catalogo' || intent === 'buscar') {
    const productos = apiResp.productos || [];
    if (productos.length > 0) {
      const titulo = intent === 'buscar'
        ? '*🔍 Resultados para "' + prep.args + '"*'
        : '*📦 Catálogo de Productos*';
      respuesta = titulo + '\n\n';
      for (const p of productos) {
        respuesta += '*' + p.codigo + '* — ' + p.descripcion + '\n';
        respuesta += '   ' + (p.unidad ? p.unidad + ' · ' : '') + '$' + Number(p.precio).toFixed(2) + '\n\n';
      }
      respuesta += '_Escribe *3 [código]* para más detalles o *5* para pedir_';
    } else {
      respuesta = intent === 'buscar'
        ? 'No encontré productos con "' + prep.args + '".\nPrueba con otro término.'
        : 'No hay productos disponibles en este momento.';
    }

  } else if (intent === 'precio') {
    if (apiResp.error) {
      respuesta = 'Producto "' + prep.args + '" no encontrado.';
    } else {
      respuesta = '*💲 ' + apiResp.descripcion + '*\n\n' +
        'Código: ' + apiResp.codigo + '\n' +
        (apiResp.departamento ? 'Depto: ' + apiResp.departamento + '\n' : '') +
        (apiResp.unidad ? 'Unidad: ' + apiResp.unidad + '\n' : '') +
        'Precio: *$' + Number(apiResp.precio).toFixed(2) + '*';
    }

  } else if (intent === 'estado') {
    if (apiResp.error) {
      respuesta = '⚠️ ' + apiResp.error;
    } else {
      respuesta = '*📝 Consulta de Cuenta*\n' +
        'Operador: _' + apiResp.operador + '_\n' +
        'Cliente: *' + apiResp.cliente.nombre + '*\n' +
        'RIF: ' + apiResp.cliente.ciRif + '\n\n';
      const facturas = apiResp.facturasPendientes || [];
      if (facturas.length > 0) {
        respuesta += '*Facturas pendientes:*\n';
        for (const f of facturas) {
          const venc = f.vencida ? ' ⚠️ VENCIDA' : '';
          respuesta += '• ' + f.concepto + ': $' + Number(f.saldo).toFixed(2) + venc + '\n';
        }
        respuesta += '\n';
      }
      respuesta += '*Deuda total:* $' + Number(apiResp.totalDeuda).toFixed(2) + '\n';
      respuesta += '*Total abonos:* $' + Number(apiResp.totalAbonos).toFixed(2) + '\n';
      if (apiResp.saldoFavor > 0) {
        respuesta += '*Saldo a favor:* $' + Number(apiResp.saldoFavor).toFixed(2) + '\n';
      }
    }

  } else if (intent === 'pedido') {
    if (apiResp.error) {
      respuesta = '⚠️ ' + apiResp.error;
    } else {
      const datos = JSON.parse(prep.args || '{}');
      respuesta = '*✅ Pedido recibido*\n\n' +
        'Cliente: *' + (datos.nombre || '') + '*\n' +
        'Tel: ' + (datos.tel || '') + '\n' +
        'Productos: ' + (datos.items || '') + '\n\n' +
        'Nuestro equipo de ventas se comunicará contigo pronto.\n' +
        '_Escribe *menu* para volver al inicio._';
    }

  } else {
    respuesta = 'Error procesando la solicitud.';
  }
} catch (e) {
  respuesta = 'Ocurrió un error. Intenta de nuevo más tarde.';
}

return [{ json: { respuesta } }];
